<script module lang="ts">
/**
 * FileUpload.Row: one file, with its status and its controls, playing its exit when it leaves.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/file-upload.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot, watchEffect } from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/file-upload.module.css'
import Button from './Button.svelte'
import Progress from '../structure/Progress.svelte'
import type { FileUploadItem } from './FileUpload.svelte'

export interface FileUploadRowProps {
  file: FileUploadItem
  /**
   * False once the file has left the list, while the row plays its exit.
   */
  open: boolean
  /**
   * The size, formatted by the messages.
   */
  size?: string
  /**
   * The app handles a retry, so a failed row offers one.
   */
  retryable: boolean
  retryLabel: string
  removeLabel: string
  progressLabel: string
  onRetry?: () => void
  onRemove?: () => void
  /**
   * The exit has played, and the member can drop the row.
   */
  onDone?: () => void
}
</script>

<script lang="ts">
let {
  file,
  open,
  size,
  retryable,
  retryLabel,
  removeLabel,
  progressLabel,
  onRetry,
  onRemove,
  onDone,
}: FileUploadRowProps = $props()
const joined = joinSlot(undefined, () => ({ size: size }))
let row = $state<HTMLElement | null>(null)
const present = usePresence(
  () => open,
  () => row,
  'fileupload.row',
)
const effect1 = () => {
  present.current || onDone?.()
}
watchEffect(effect1, { watch: () => present.current, mount: false })
</script>

{@render joined.start?.()
}{#if joined.shown
  }<li bind:this={row} class={styles.row} data-status={file.status}
    ><span class={styles.rowIcon}><Icon name="document" /></span
    ><span class={styles.details}
      ><span class={styles.name}>{file.name}</span
      >{#if size !== undefined}<span class={styles.meta}>{size}</span>{/if
      }{#if file.status === 'error' && file.message !== undefined
        }<span class={styles.message}>{file.message}</span
      >{/if
    }</span
    >{#if file.status === 'uploading'
      }<span class={styles.trailing}
        ><span class={styles.progress}
          ><Progress value={file.progress ?? 0} label={progressLabel}
        /></span
        ><span class={styles.percent}>{`${Math.round(file.progress ?? 0)}%`}</span
      ></span
    >{/if
    }{#if file.status === 'done'}<span class={styles.done}><Icon name="success" /></span>{/if
    }{#if file.status === 'error' && retryable
      }<Button
        variant="ghost"
        tone="neutral"
        size="sm"
        iconOnly={true}
        icon="refresh"
        label={retryLabel}
        onClick={() => { onRetry?.() }}
    />{/if
    }<Button
      variant="ghost"
      tone="neutral"
      size="sm"
      iconOnly={true}
      icon="close"
      label={removeLabel}
      onClick={() => { onRemove?.() }}
  /></li
>{/if
}{@render joined.end?.()}
